// test/semver.test.js
const { strictEqual, deepStrictEqual } = require('assert');
const compareSemver = require('./semver.cjs').compareSemver;

describe('compareSemver', () => {
    // Examples from the specification
    it('should return -1 for "1.2.3" and "1.2.4"', () => {
        strictEqual(compareSemver('1.2.3', '1.2.4'), -1);
    });

    it('should return -1 for "2.0.0" and "10.0.0"', () => {
        strictEqual(compareSemver('2.0.0', '10.0.0'), -1);
    });

    it('should return -1 for "1.0.0-alpha" and "1.0.0"', () => {
        strictEqual(compareSemver('1.0.0-alpha', '1.0.0'), -1);
    });

    it('should return -1 for "1.0.0-alpha" and "1.0.0-alpha.1"', () => {
        strictEqual(compareSemver('1.0.0-alpha', '1.0.0-alpha.1'), -1);
    });

    it('should return -1 for "1.0.0-alpha.1" and "1.0.0-alpha.beta"', () => {
        strictEqual(compareSemver('1.0.0-alpha.1', '1.0.0-alpha.beta'), -1);
    });

    it('should return -1 for "1.0.0-beta.2" and "1.0.0-beta.11"', () => {
        strictEqual(compareSemver('1.0.0-beta.2', '1.0.0-beta.11'), -1);
    });

    it('should return -1 for "1.0.0-rc.1" and "1.0.0"', () => {
        strictEqual(compareSemver('1.0.0-rc.1', '1.0.0'), -1);
    });

    it('should return 0 for "1.0.0+build.5" and "1.0.0"', () => {
        strictEqual(compareSemver('1.0.0+build.5', '1.0.0'), 0);
    });

    // Additional test cases
    it('should return -1 for "1.2.3" and "1.2.3-beta.23"', () => {
        strictEqual(compareSemver('1.2.3', '1.2.3-beta.23'), 1);
    });

    it('should return -1 for "1.2.3-beta.23" and "1.2.3-beta.33"', () => {
        strictEqual(compareSemver('1.2.3-beta.23', '1.2.3-beta.33'), -1);
    });

    it('should return 0 for "1.2.3-beta.23" and "1.2.3-beta.23"', () => {
        strictEqual(compareSemver('1.2.3-beta.23', '1.2.3-beta.23'), 0);
    });

    it('should return -1 for "1.2.3-beta.33" and "1.2.3-beta"', () => {
        strictEqual(compareSemver('1.2.3-beta.33', '1.2.3-beta'), -1);
    });

    it('should return 0 for "1.0.0" and "1.0.0"', () => {
        strictEqual(compareSemver('1.0.0', '1.0.0'), 0);
    });

    it('should return -1 for "1.0.0-alpha.1" and "1.0.0-alpha.1.1"', () => {
        strictEqual(compareSemver('1.0.0-alpha.1', '1.0.0-alpha.1.1'), -1);
    });

    it('should return -1 for "1.0.0-alpha.1" and "1.0.0-alpha.beta.1"', () => {
        strictEqual(compareSemver('1.0.0-alpha.1', '1.0.0-alpha.beta.1'), -1);
    });

    it('should return -1 for "1.0.0-alpha" and "1.0.0-alpha.beta.1"', () => {
        strictEqual(compareSemver('1.0.0-alpha', '1.0.0-alpha.beta.1'), -1);
    });

    // Edge cases
    it('should return -1 for "1.0.0-alpha" and "1.0.0-alpha.0"', () => {
        strictEqual(compareSemver('1.0.0-alpha', '1.0.0-alpha.0'), -1);
    });

    it('should return -1 for "1.0.0-alpha.1" and "1.0.0-alpha.1.0"', () => {
        strictEqual(compareSemver('1.0.0-alpha.1', '1.0.0-alpha.1.0'), -1);
    });

    it('should return 0 for "1.0.0+build.1" and "1.0.0+build.1"', () => {
        strictEqual(compareSemver('1.0.0+build.1', '1.0.0+build.1'), 0);
    });
});

